INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15101, 'Psalms 121:8', 'Psalms', 121, 8, '&nbsp;مالِک خُدائ به ستا په تلو راتلو کښې حفاظت کوى، د اوس نه تر ابده پورې به ستا حفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15102, 'Psalms 122:1', 'Psalms', 122, 1, '&nbsp;ما به د هغوئ سره خوشحالى کوله چا چې به ما ته وئيل، ”راځئ چې د مالِک خُدائ کور ته ځو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15103, 'Psalms 122:2', 'Psalms', 122, 2, '&nbsp;اے يروشلمه اوس مونږ ستا په دروازو کښې ولاړ يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15104, 'Psalms 122:3', 'Psalms', 122, 3, '&nbsp;يروشلم د هغه ښار په شان جوړ شوے دے، چې ټول ښار د يو بل پسې پيوسته جوړ شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15105, 'Psalms 122:4', 'Psalms', 122, 4, '&nbsp;چرته چې د بنى اِسرائيلو قبيلې بره ورخېژى، د مالِک خُدائ قبيلې ورخېژى، چې د مالِک خُدائ د نوم ثناء ووائى، د هغه شريعت په مطابق چې بنى اِسرائيلو ته ورکړے شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15106, 'Psalms 122:5', 'Psalms', 122, 5, '&nbsp;هلته د اِنصاف دپاره د عدالت تختونه قائم دى، د داؤد د خاندان تختونه قائم دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15107, 'Psalms 122:6', 'Psalms', 122, 6, '&nbsp;د يروشلم د سلامتيا دپاره دُعا وغواړه، ”او څوک چې کوى تا سره مينه آباد دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15108, 'Psalms 122:7', 'Psalms', 122, 7, '&nbsp;او ستا په دېوالونو کښې دې سلامتيا وى، او ستا په برجونو کښې دې امن او قرارى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15109, 'Psalms 122:8', 'Psalms', 122, 8, '&nbsp;زما د وروڼو او دوستانو په خاطر يې غواړم، ”په تا کښې دې امن او سلامتى وى،“ زۀ به دا وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15110, 'Psalms 122:9', 'Psalms', 122, 9, '&nbsp;او زمونږ د مالِک خُدائ او خُدائ پاک د کور په خاطر يې غواړم، او زۀ به ستا خير خواه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15111, 'Psalms 123:1', 'Psalms', 123, 1, '&nbsp;ما خپلې سترګې تا ته نيولې دى، تا ته د چا تخت چې په آسمان کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15112, 'Psalms 123:2', 'Psalms', 123, 2, '&nbsp;لکه څنګه چې غلام د خپل مالِک لاس ته ګورى، او لکه څنګه چې وينځه د خپلې بى‌بى لاس ته ګورى، نو دغه شان زمونږ سترګې د مالِک خُدائ زمونږ خُدائ پاک ته ګورى، تر هغې چې هغه مونږ ته خپل رحم وښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15113, 'Psalms 123:3', 'Psalms', 123, 3, '&nbsp;په مونږ باندې رحم وکړه، اے مالِکه خُدايه، تۀ په مونږ ورحمېږه، ځکه چې مونږ د حد نه زيات سپک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15114, 'Psalms 123:4', 'Psalms', 123, 4, '&nbsp;د کبرژنو ډيرې زياتې مسخرې مونږ تېرې کړې دى، مونږ د مغرورانو ډېر سپکاوے زغملے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15115, 'Psalms 124:1', 'Psalms', 124, 1, '&nbsp;کۀ چرته مالِک خُدائ زمونږ مل نۀ وے، نو بنى اِسرائيل دې داسې وائى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15116, 'Psalms 124:2', 'Psalms', 124, 2, '&nbsp;کۀ چرته مالِک خُدائ زمونږ مل نۀ وے، کله چې خلقو په مونږ حمله وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15117, 'Psalms 124:3', 'Psalms', 124, 3, '&nbsp;کله چې هغوئ زمونږ خلاف سخت په قهر وُو، نو دوئ به مونږ ژوندى تير کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15118, 'Psalms 124:4', 'Psalms', 124, 4, '&nbsp;نو سېلاب به مونږ راګېر کړى وُو، او خوړ به مونږ جارُو کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15119, 'Psalms 124:5', 'Psalms', 124, 5, '&nbsp;او غضبناکو اوبو به مونږ لاندې کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15120, 'Psalms 124:6', 'Psalms', 124, 6, '&nbsp;مالِک خُدائ ته دې ثناء صِفت وى، څوک چې به مونږ د هغوئ د غاښونو شلولو ته ورنۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15121, 'Psalms 124:7', 'Psalms', 124, 7, '&nbsp;مونږ لکه د مرغۍ په شان د ښکارى د دام نه وتښتېدلو، او جال شلېدلے وو او مونږ ترې وتښتېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15122, 'Psalms 124:8', 'Psalms', 124, 8, '&nbsp;زمونږ مدد د مالِک خُدائ په نوم کښې دے، چې د آسمان او زمکې جوړونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15123, 'Psalms 125:1', 'Psalms', 125, 1, '&nbsp;هغوئ څوک چې په مالِک خُدائ ايمان لرى د صيون د غرۀ په شان دى، کوم چې نۀ خوځيږى او د تل دپاره قائم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15124, 'Psalms 125:2', 'Psalms', 125, 2, '&nbsp;لکه څنګه چې غرونه د يروشلم نه راتاو دى، نو دغه شان مالِک خُدائ د خپلو خلقو نه راتاو دے يعنې د اوس نه تر ابده پورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15125, 'Psalms 125:3', 'Psalms', 125, 3, '&nbsp;د بدعملو حکومت او اقتدار به پاتې نۀ شى، په هغه زمکه کومه چې صادقانو ته ورکړے شوې ده، ځکه هسې نۀ چې صادقان هم په بد عملونو باندې اخته شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15126, 'Psalms 125:4', 'Psalms', 125, 4, '&nbsp;اے مالِکه خُدايه هغوئ سره ښۀ کوئ څوک چې ښۀ وى، هغوئ سره د چا چې زړونه صادق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15127, 'Psalms 125:5', 'Psalms', 125, 5, '&nbsp;خو هغوئ څوک چې بدو او کږو لارو ته اوړى، مالِک خُدائ به هغه بدکاران وشړى، سلامتيا دې په بنى اِسرائيلو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15128, 'Psalms 126:1', 'Psalms', 126, 1, '&nbsp;کله چې مالِک خُدائ شړلے شوى قېديان واپس صيون ته راوستل، مونږ د هغه خلقو په شان وُو چا چې خوب ليدلے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15129, 'Psalms 126:2', 'Psalms', 126, 2, '&nbsp;زمونږ خولې د خندا نه ډکې وې، او زمونږ په ژبو چې د خوشحالۍ سندرې وې. نو بيا دا د قومونو په مينځ کښې وئيلے کېدل، چې، ”مالِک خُدائ د هغوئ دپاره لوئ کارونه کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15130, 'Psalms 126:3', 'Psalms', 126, 3, '&nbsp;مالِک خُدائ مونږ له لوئ کارونه کړى دى، او مونږ ډېر خوشحاله شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15131, 'Psalms 126:4', 'Psalms', 126, 4, '&nbsp;مالِکه خُدايه زمونږ حالات دوباره په ځائ کړه، لکه څنګه چې نِهرونه صحراګانې تازه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15132, 'Psalms 126:5', 'Psalms', 126, 5, '&nbsp;څوک چې په اوښکو سره کَر وکړى، نو هغوئ به لَو په خوشحالۍ سره وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15133, 'Psalms 126:6', 'Psalms', 126, 6, '&nbsp;او څوک چې په ژړا سره بهر ته ځى، او تخم د کَرلو دپاره وړى، خو هغوئ به په سندرو او خوشحالۍ سره واپس راشى، کله چې ګېډۍ په لاس کښې راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15134, 'Psalms 127:1', 'Psalms', 127, 1, '&nbsp;ترڅو چې مالِک خُدائ يو کور جوړ نۀ کړى، د هغې د جوړونکى محنت بې‌کاره دے. ترڅو چې د خُدائ نظر په ښار نۀ وى، د هغې چوکيداران بې‌کاره ولاړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15135, 'Psalms 127:2', 'Psalms', 127, 2, '&nbsp;خوراک پسې وختى پاڅېدل او تر ناوخته ويښ پاتې کېدل بې‌فائدې دى، خُدائ پاک چې چا سره مينه کوى کۀ هغه اودۀ وى نو ورته خوراک ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15136, 'Psalms 127:3', 'Psalms', 127, 3, '&nbsp;د مالِک خُدائ د طرف نه زامن ميراث دے، ماشومان د هغۀ د خوا نه اجر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15137, 'Psalms 127:4', 'Psalms', 127, 4, '&nbsp;لکه څنګه چې د جنګيالى په لاس کښې غشى وى، داسې وى لکه د چا چې په ځوانۍ کښې زامن وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15138, 'Psalms 127:5', 'Psalms', 127, 5, '&nbsp;هغه څوک به بختور وى، چې د چا چې تيلۍ د دغه شان غشو نه ډکه وى، نو دوئ به ونۀ شرمولے شى، کله چې دوئ د ښار په دروازو کښې د دشمن سره په مقابله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15139, 'Psalms 128:1', 'Psalms', 128, 1, '&nbsp;بختور دى هغوئ ټول څوک چې د مالِک خُدائ نه يريږى، او څوک چې د هغۀ په لارو روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15140, 'Psalms 128:2', 'Psalms', 128, 2, '&nbsp;تاسو به د خپل محنت مېوه وخورئ، برکتونه او خير به ستاسو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15141, 'Psalms 128:3', 'Psalms', 128, 3, '&nbsp;او ستا ښځه به لکه د مېوه داره انګورو بوټى په شان وى، او ستا زامن به لکه د زيتون بوټى په شان وى، ستا د دسترخوان نه به راچاپيره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15142, 'Psalms 128:4', 'Psalms', 128, 4, '&nbsp;نو دغه شان سړے به بختور وى، څوک چې د مالِک خُدائ نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15143, 'Psalms 128:5', 'Psalms', 128, 5, '&nbsp;د صيون نه دې مالِک خُدائ تا له برکت درکړى، او تۀ په خپل ټول ژوند کښې د يروشلم آبادى وګورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15144, 'Psalms 128:6', 'Psalms', 128, 6, '&nbsp;او تۀ دې تر هغې پورې ژوندے پاتې شې چې د خپلو بچو بچى وګورې، په بنى اِسرائيلو دې سلامتيا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15145, 'Psalms 129:1', 'Psalms', 129, 1, '&nbsp;”هغوئ د ماشوموالى نه په ما باندې ډېر زياتے کړے دے،“ بنى اِسرائيل پرېږده چې داسې ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15146, 'Psalms 129:2', 'Psalms', 129, 2, '&nbsp;”هغوئ د ماشوموالى نه په ما باندې ډېر زياتے کړے دے، خو هغوئ ما ته شکست نۀ دے راکړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15147, 'Psalms 129:3', 'Psalms', 129, 3, '&nbsp;زما دشمنانو زۀ دومره وهلے يم، لکه د يوه کوونکى په شان يې زما په ملا اوږدې پولې جوړې کړې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15148, 'Psalms 129:4', 'Psalms', 129, 4, '&nbsp;خو مالِک خُدائ صادق دے، او زۀ يې د شريرانو د رسۍ نه آزاد کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15149, 'Psalms 129:5', 'Psalms', 129, 5, '&nbsp;هر څوک چې د صيون نه کرکه کوى، هغوئ به په شرم وشرميږى او شکست به وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15150, 'Psalms 129:6', 'Psalms', 129, 6, '&nbsp;هغوئ دې د چت د واښو په شان اوچ شى، کوم چې د غټېدو نه وړاندې اوچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15151, 'Psalms 129:7', 'Psalms', 129, 7, '&nbsp;د لَوګرو لاسونه دې پرې ډک نۀ شى، څوک ‎يې چې راټولوى نو د هغۀ غېږه دې پرې ډکه نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15152, 'Psalms 129:8', 'Psalms', 129, 8, '&nbsp;هغوئ څوک چې پرې تېريږى دا دې نۀ وائى، چې، ”د مالِک خُدائ برکت دې په تا وى، مونږ تا ته د مالِک خُدائ په نوم برکت درکوو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15153, 'Psalms 130:1', 'Psalms', 130, 1, '&nbsp;اے مالِکه خُدايه، لاندې د ژورې نه تا ته ژړا کومه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15154, 'Psalms 130:2', 'Psalms', 130, 2, '&nbsp;مالِکه خُدايه، زما ژړا ته غوږ شه، او په ما رحم وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15155, 'Psalms 130:3', 'Psalms', 130, 3, '&nbsp;اے مالِکه خُدايه، کۀ تا، د ګناهونو حساب کړے وے، اے مالِکه خُدايه، نو څوک ستا مخکښې ودرېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15156, 'Psalms 130:4', 'Psalms', 130, 4, '&nbsp;خو تا سره د معافۍ امکان شته دے، نو په دې وجه خُدايه، چې مونږ ستا په يره وپوهېږو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15157, 'Psalms 130:5', 'Psalms', 130, 5, '&nbsp;زۀ د مالِک خُدائ انتظار کومه، او زما روح هم انتظار کوى، او زما اُميد د هغۀ په کلام باندې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15158, 'Psalms 130:6', 'Psalms', 130, 6, '&nbsp;زما روح د مالِک خُدائ انتظار کوى، د يو څوکيدار نه زيات څوک چې د سحر کېدو انتظار کوى، آو، د يو څوکيدار نه زيات څوک چې د سحر کېدو انتظار کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15159, 'Psalms 130:7', 'Psalms', 130, 7, '&nbsp;اے بنى اِسرائيلو، د مالِک خُدائ اُميد ساتئ، د مالِک خُدائ مينه ابدى ده او هغۀ سره پوره خلاصون دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15160, 'Psalms 130:8', 'Psalms', 130, 8, '&nbsp;او هغه په خپله به د هغوئ د ټولو ګناهونو نه د بنى اِسرائيلو فديه ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15161, 'Psalms 131:1', 'Psalms', 131, 1, '&nbsp;زما زړۀ کبرژن نۀ دے اے مالِکه خُدايه، زما سترګې مغروره نۀ دى او نۀ خپل ځان په غټو مسائيلو کښې راګېروم، او نۀ په هغه حېرانونکى څيزونو کوم چې زما د فکر نه بهر دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15162, 'Psalms 131:2', 'Psalms', 131, 2, '&nbsp;خو ما خپل روح په آرام او خاموش کړو، لکه څنګه چې د غېږې ماشوم د خپلې مور سره په آرام وى. نو دغه شان زما روح به په ما کښې په آرام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15163, 'Psalms 131:3', 'Psalms', 131, 3, '&nbsp;اے بنى اِسرائيلو په مالِک خُدائ باندې توکل کوئ د اوس نه تر ابده پورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15164, 'Psalms 132:1', 'Psalms', 132, 1, '&nbsp;اے مالِکه خُدايه داؤد ياد ساته او ټول هغه کړاونه کوم چې هغۀ وزغمل ياد ساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15165, 'Psalms 132:2', 'Psalms', 132, 2, '&nbsp;هغۀ د مالِک خُدائ سره قسم وخوړلو او د يعقوب د قادر مطلق خُدائ پاک سره يې وعده وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15166, 'Psalms 132:3', 'Psalms', 132, 3, '&nbsp;”او زۀ به خپل کور ته نۀ ورننوځم او نۀ به خپل کټ کښې آرام وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15167, 'Psalms 132:4', 'Psalms', 132, 4, '&nbsp;او نۀ به سترګې پټې کړم او نۀ به سترګې مرغۍ کېدو ته پرېږدم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15168, 'Psalms 132:5', 'Psalms', 132, 5, '&nbsp;تر دې چې مالِک خُدائ له ځائ پېدا کړم، او د يعقوب قادر خُدائ له د اوسېدو ځائ پېدا کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15169, 'Psalms 132:6', 'Psalms', 132, 6, '&nbsp;مونږ د لوظ صندوق ذکر په اِفراته کښې واورېدلو، او مونږ هغه د يعريم په مُلک کښې وموندلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15170, 'Psalms 132:7', 'Psalms', 132, 7, '&nbsp;”راځئ چې مونږه د هغۀ د اوسېدو ځائ ته لاړ شُو، راځئ چې د هغۀ د پښو چوکۍ په وړاندې هغۀ ته سجده وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15171, 'Psalms 132:8', 'Psalms', 132, 8, '&nbsp;مالِکه خُدايه پاڅه او خپل مقدس عرش ته دې راشه، خپل د لوظ صندوق سره چې ستا د قدرت نښه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15172, 'Psalms 132:9', 'Psalms', 132, 9, '&nbsp;ستا اِمامان دې د صداقت جامې واچوى، او ستا مقدسين دې د خوشحالۍ سندرې ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15173, 'Psalms 132:10', 'Psalms', 132, 10, '&nbsp;ستا د خِدمتګار داؤد په خاطر خپل غوره شوى دې مۀ رد کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15174, 'Psalms 132:11', 'Psalms', 132, 11, '&nbsp;مالِک خُدائ د خپل خِدمتګار داؤد سره قسم وکړو يو داسې پوخ قسم چې هغه به نۀ ماتوى، ”چې زۀ به يو کس ستا د نسل نه ستا په تخت کښېنوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15175, 'Psalms 132:12', 'Psalms', 132, 12, '&nbsp;کۀ ستا زامن زما لوظ پوره وساتى او ستا هغه اصُول منى کوم چې ورته وښايم، نو بيا به د هغوئ زامن تر ابده پورې ستا په تخت ناست وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15176, 'Psalms 132:13', 'Psalms', 132, 13, '&nbsp;ځکه چې مالِک خُدائ صيون خوښ کړے دے، هغۀ د اوسېدو دپاره دغه ځائ خوښ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15177, 'Psalms 132:14', 'Psalms', 132, 14, '&nbsp;”دا زما تر ابده پورې د آرام ځائ دے، او هلته به زۀ په تخت کښېنم د کوم چې ما خواهش کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15178, 'Psalms 132:15', 'Psalms', 132, 15, '&nbsp;دا به زۀ په ډېر پېداوار باندې بختور کړم، او د هغې غريبان به زۀ په خوراک باندې ماړۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15179, 'Psalms 132:16', 'Psalms', 132, 16, '&nbsp;زۀ به د خلاصون جامې ورواغوندم د دې اِمامانو ته، د هغې مقدسين دې د خوشحالۍ سندرې ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15180, 'Psalms 132:17', 'Psalms', 132, 17, '&nbsp;دلته به زۀ د داؤد د فخر ښکر جوړ کړم، د خپل مقرر شوى کس دپاره به ډيوه بله کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15181, 'Psalms 132:18', 'Psalms', 132, 18, '&nbsp;زۀ به د هغې دشمنانو ته د شرم جامې واغوندم، او د هغۀ په سر تاج به د لوئې مرتبې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15182, 'Psalms 133:1', 'Psalms', 133, 1, '&nbsp;څومره ښۀ او د مزې خبره ده کله چې وروڼه په يو اتفاق سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15183, 'Psalms 133:2', 'Psalms', 133, 2, '&nbsp;دا د هغه قيمتى تېلو په شان چې په سر باندې لګولے شوى وى، او د هارون په ږيره بهېدلى وى، او د هغۀ د چُوغې په غاړه راروان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15184, 'Psalms 133:3', 'Psalms', 133, 3, '&nbsp;دا لکه د حرمون د پرخې په شان چې د صيون په غر باندې راوريږى، دا ځکه چې مالِک خُدائ هلته خپلو خلقو ته برکت ورکوى. تر دې چې ابدى ژوندون ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15185, 'Psalms 134:1', 'Psalms', 134, 1, '&nbsp;د مالِک خُدائ ثناء صِفت وکړئ اے د مالِک خُدائ ټولو خِدمتګارانو، څوک چې د شپې د مالِک خُدائ په کور کښې خِدمت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15186, 'Psalms 134:2', 'Psalms', 134, 2, '&nbsp;خپل لاسونه د خُدائ په مقدس ځائ کښې پورته کړئ. او د مالِک خُدائ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15187, 'Psalms 134:3', 'Psalms', 134, 3, '&nbsp;مالِک خُدائ د آسمان او زمکې پېدا کوونکے دے، تاسو ته دې صيون نه برکت درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15188, 'Psalms 135:1', 'Psalms', 135, 1, '&nbsp;د مالِک خُدائ ثناء صِفت وکړئ، د مالِک خُدائ د نوم ثناء صِفت وکړئ، اے د مالِک خُدائ خِدمتګارانو تاسو د هغۀ ثناء صِفت وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15189, 'Psalms 135:2', 'Psalms', 135, 2, '&nbsp;تاسو څوک چې د مالِک خُدائ کور کښې خِدمت کوئ، زمونږ د خُدائ پاک د کور په دربار کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15190, 'Psalms 135:3', 'Psalms', 135, 3, '&nbsp;د مالِک خُدائ ثناء صِفت وکړئ ځکه چې مالِک خُدائ ښۀ دے، د هغۀ د نوم ثناء صِفت وکړئ. ځکه چې ډېره مزه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15191, 'Psalms 135:4', 'Psalms', 135, 4, '&nbsp;ځکه چې مالِک خُدائ يعقوب غوره کړو، د دې دپاره چې هغه د هغۀ شى، او بنى اِسرائيل چې د هغۀ خاص ملکيت شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15192, 'Psalms 135:5', 'Psalms', 135, 5, '&nbsp;زۀ پوهېږم چې مالِک خُدائ لوئ دے، زمونږ مالِک خُدائ د نورو ټولو معبودانو نه لوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15193, 'Psalms 135:6', 'Psalms', 135, 6, '&nbsp;مالِک خُدائ هغه څۀ کوى څۀ چې هغه خوشحالوى، په ټوله زمکه او آسمانونو کښې، په سمندرونو کښې او د هغۀ په ټولو ژورو ځايونو کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15194, 'Psalms 135:7', 'Psalms', 135, 7, '&nbsp;د زمکې د آخر سر نه هغه وريځې راپورته کوى، او هغه باران سره برېښنا رالېږى او هغه هوا د خپلو ذخيرو نه رالوځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15195, 'Psalms 135:8', 'Psalms', 135, 8, '&nbsp;هغۀ وړومبى پېدا شوى ماشومان ووژل د مِصريانو، وړومبى پېدا شوى د سړو او د ځناورانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15196, 'Psalms 135:9', 'Psalms', 135, 9, '&nbsp;هغۀ په مِصر کښې معجزې او عجيبه کارونه وکړل، د فِرعون او د هغۀ د ټولو نوکرانو په خلاف.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15197, 'Psalms 135:10', 'Psalms', 135, 10, '&nbsp;هغۀ ډېرو قومونو ته شکست ورکړو او هغۀ طاقتور بادشاهان ووژل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15198, 'Psalms 135:11', 'Psalms', 135, 11, '&nbsp;د اموريانو بادشاه سيحون د بسن بادشاه عوج، هغۀ د کنعان ټول بادشاهان ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15199, 'Psalms 135:12', 'Psalms', 135, 12, '&nbsp;او هغۀ د هغوئ مُلک په ميراث کښې ورکړو، او خپلو خلقو بنى اِسرائيلو ته يې په ميراث کښې ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15200, 'Psalms 135:13', 'Psalms', 135, 13, '&nbsp;ستا نوم مالِکه خُدايه د تل دپاره ياديږى، او ستا نوم به په ټولو نسلونو کښې ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');